tool.command:

  ln -f -s ${input_trajectory_path} ${input_trajectory_path}_`echo $$`.${input_trajectory_path.ext};

  ln -f -s ${input_topology_path} ${input_topology_path}_`echo $$`.${input_topology_path.ext};

#if $config.sele == "option1":
    ln -s -f ${config.properties} ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

mdfeaturizer

#if $config.sele == "option1":
    --config ${config.properties}_`echo $$`.${config.properties.ext}
  #else if $config.sele == "option2":
    --config '${config.jsonstr}'
  #else if $config.sele == "option3":
    --config '__oc____dq__properties__dq__:__oc____dq__cartesian__dq__:${properties.cartesian},__dq__distances__dq__:${properties.distances},__dq__angles__dq__:${properties.angles},__dq__dihedrals__dq__:${properties.dihedrals},__dq__options__dq__:${properties.options}__cc____cc__'
  #end if

  #if str($input_trajectory_path) != 'None':
    --input_trajectory_path ${input_trajectory_path}_`echo $$`.${input_trajectory_path.ext}
  #end if

  #if str($input_topology_path) != 'None':
    --input_topology_path ${input_topology_path}_`echo $$`.${input_topology_path.ext}
  #end if


  --output_dataset_pt_path $outname_output_dataset_pt_path

  --output_stats_pt_path $outname_output_stats_pt_path
;
#if $config.sele == "option1":
    rm -f ${config.properties}_`echo $$`.${config.properties.ext};
  #end if

  rm -f ${input_trajectory_path}_`echo $$`.${input_trajectory_path.ext};

  rm -f ${input_topology_path}_`echo $$`.${input_topology_path.ext};


  if test -f $outname_output_dataset_pt_path; then mv $outname_output_dataset_pt_path $output_dataset_pt_path; fi;

  if test -f $outname_output_stats_pt_path; then mv $outname_output_stats_pt_path $output_stats_pt_path; fi;
